#include <stdio.h>
#include <stdlib.h>

int main(int argc, char **argv) {
    int sku, qty;
    long revenue = 0;
    long stock[5] = {0};
    long price[5] = {10, 20, 30, 40, 50};

    for (int i = 1; i < argc; i += 3) {
        char op = *argv[i];
        sku = strtol(argv[i + 1], NULL, 10);
        qty = strtol(argv[i + 2], NULL, 10);

        if (op == 'S') {
            if (stock[sku] < qty) {
                printf("INSUFFICIENT_STOCK sku=%ld\n", sku);
            } else {
                stock[sku] -= qty;
                revenue += price[sku] * qty;
                printf("SELL sku=%ld qty=%ld revenue+=%ld\n", sku, qty, price[sku] * qty);
            }
        } else if (op == 'R') {
            stock[sku] += qty;
            printf("RESTOCK sku=%ld qty=%ld\n", sku, qty);
        } else {
            printf("INVALID_OP\n");
        }
    }

    printf("FINAL stock=");
    for (int i = 0; i < 5; i++) {
        printf("%ld", stock[i]);
        if (i < 4) printf(",");
    }
    printf(" revenue=%ld\n", revenue);

    return 0;
}
